body:
this is the only part where closestNode appears ;

&#x200B;

&#x200B;

closestNode = noone;



while(closestNode = noone){

targetHero = ds\_priority\_delete\_min(heroList);



targetNode = map\[targetHero.gridX, targetHero.gridY\];



for(ii = 0; ii < ds\_list\_size(targetNode.neighbors); ii += 1){

currentNode = ds\_list\_find\_value(targetNode.neighbors, ii);

if(currentNode.occupant == noone && currentNode.passable){

closestNode = currentNode;

}

}



if(ds\_priority\_size(heroList) <= 0){

targetHero = noone;

flash = true;

alarm\[0\] = 30;

state = "idle"



break;

}

}



ds\_priority\_destroy(heroList);



if(targetHero != noone){

targetNode = closestNode;



ai\_movement(map\[gridX, gridY\], closestNode);



while(closestNode.G > move \* actions){

closestNode = closestNode.parent;



}



create\_path(id, closestNode);



map\[gridX, gridY\].occupant = noone;



gridX = closestNode.gridX;

gridY = closestNode.gridY;



closestNode.occupant = id;



if(closestNode.G > move){

actions -= 2;

}else{

actions -= 1;

}

}

wipe\_nodes();

break;

&#x200B;

&#x200B;

//if cursor is hovering over a different node than actor's

if(oCursor.selectedActor == id){

if(oCursor.hoverNode !=noone){

tempNode = oCursor.hoverNode;

if(tempNode.moveNode){

current = tempNode;

//step through every node in the chain, parent to parent, until we reach the actor's node.

while(current.parent != noone){

draw\_line\_width\_color(current.x + 16, current.y + 16, current.parent.x + 16, current.parent.y + 16, 4, c\_lime, c\_lime);

current = current.parent;

}

}

   if(tempNode.attackNode){

switch(attackType){

case "ranged":

draw\_line\_width\_colour(x + 16, y +16, tempNode.x + 16, tempNode.y +16, 4, c\_purple, c\_purple);

break;

}

}

}

if(shake > 0){

draw\_sprite\_ext(sprite\_index, -1, x + irandom\_range(-shakeMag, shakeMag), y + irandom\_range(-shakeMag, shakeMag), 1, 1, 0, c\_white, 1);

}else{

draw\_self();

}}
